79|fn canonical(path: &str) -> bool {
80|    Path::new(path).is_absolute()
81|        && Path::new(path)
82|            .components()
83|            .all(|p| matches!(p, Component::RootDir | Component::Normal(_)))
84|}
85|fn native_uuid(instance: &JsonValue) -> Result<&str> {
86|    let value = instance["config"]["volatile.uuid"]
87|        .as_str()
88|        .context("native UUID missing")?;
89|    ensure!(
90|        uuid::Uuid::parse_str(value)?.to_string() == value,
91|        "native UUID is noncanonical"
92|    );
93|    Ok(value)
94|}
95|fn canonical_key(key: &str) -> Result<()> {
96|    let decoded = base64::engine::general_purpose::STANDARD.decode(key)?;
97|    ensure!(
98|        decoded.len() == 32 && base64::engine::general_purpose::STANDARD.encode(decoded) == key,
99|        "noncanonical public key"
100|    );
101|    Ok(())
102|}
103|
104|impl CleanPlan {
105|    fn validate(&self) -> Result<()> {
106|        canonical_key(&self.wireguard_pubkey)?;
107|        ensure!(
108|            matches!(self.version, 2 | 3 | 4)
109|                && self.session_id
110|                    == op_identity::session::derive_session_id(&self.wireguard_pubkey)
111|                && control_plane_chatbot_session_id().as_deref() == Some(self.session_id.as_str())
112|                && configured_chatbot_key().as_deref() == Some(self.wireguard_pubkey.as_str()),
113|            "clean adoption is only for the configured chatbot key"
114|        );
115|        if self.version == 4 {
116|            let layout = self.partitioned_overlay.as_ref().context("partitioned overlay pins absent")?;
117|            let root = &layout.root_partition;
118|            let upgrade = &layout.upgrade_partition;
119|            ensure!(self.binding.device_path == "/var/lib/3tched-leaf-pool/3tchedChatbot.img"
120|                && self.binding.mount_point == "/var/lib/3tched-leaf-pool/.mounts/3tchedChatbot/root"
121|                && root.start_sector == 2048 && root.sectors >= 2_097_152
122|                && root.start_sector.checked_add(root.sectors) == Some(upgrade.start_sector)
123|                && upgrade.sectors >= 2_097_152
124|                && upgrade.start_sector.checked_add(upgrade.sectors)
125|                    == self.leaf_size.checked_div(512).and_then(|sectors| sectors.checked_sub(2048))
126|                && self.leaf_size % 512 == 0,
127|                "partition geometry or external mount paths differ");
128|            let mut uuids = HashSet::new();
129|            for value in [&layout.disk_guid, &root.partuuid, &upgrade.partuuid, &layout.upgrade_fsid,
130|                &layout.host_upgrade_fsid, &self.seed_fsid, &self.binding.btrfs_uuid] {
131|                ensure!(uuid::Uuid::parse_str(value)?.to_string() == *value && uuids.insert(value),
132|                    "partition or filesystem identities are invalid or reused");
133|            }
134|            ensure!(layout.host_upgrade_fsid == "5a88e7cd-9701-40a7-8301-ef076761886c",
135|                "host upgrade identity differs");
136|        } else {
137|            ensure!(self.partitioned_overlay.is_none(), "legacy plan includes partitioned layout");
138|        }
139|        ensure!(
140|            self.binding.cozo_id == self.session_id
141|                && self.binding.attached
142|                && self.leaf_inode > 0
143|                && self.leaf_size >= 1024 * 1024 * 1024
144|                && self.persist_inode > 256
145|                && self.seed_generation > 0
146|                && !self.instance_etag.is_empty(),
147|            "invalid clean storage/native provenance"
148|        );
149|        for path in [
150|            &self.seed_device,
151|            &self.binding.device_path,
152|            &self.binding.mount_point,
153|            &self.native_root,
154|            &self.pool_source,
155|        ] {
156|            ensure!(canonical(path), "noncanonical clean plan path");
157|        }
158|        ensure!(
159|            self.seed_device.starts_with("/dev/")
160|                && !self.binding.device_path.starts_with("/dev/")
161|                && uuid::Uuid::parse_str(&self.seed_fsid)?.to_string() == self.seed_fsid
162|                && uuid::Uuid::parse_str(&self.binding.btrfs_uuid)?.to_string()
163|                    == self.binding.btrfs_uuid
164|                && self.seed_fsid != self.binding.btrfs_uuid,
165|            "invalid shared seed/leaf identities"
166|        );
167|        ensure!(
168|            self.members.len() == 7 && MEMBERS.iter().all(|name| self.members.contains_key(*name)),
169|            "clean plan requires exactly seven inherited siblings"
170|        );
171|        let mut ids = HashSet::new();
172|        let mut uuids = HashSet::new();
173|        for pin in self.members.values() {
174|            ensure!(
175|                pin.id >= 256
176|                    && uuid::Uuid::parse_str(&pin.uuid)?.to_string() == pin.uuid
177|                    && ids.insert(pin.id)
178|                    && uuids.insert(&pin.uuid),
179|                "invalid inherited member identities"
180|            );","total_lines":696,"file_size":27970,"truncated":true,"hint":"Use offset=181 to continue reading (showing 1-180 of 696 lines)","is_binary":false,"is_image":false,"not_found":false}

{"content":"1|//! Global native-name allocation. Never infer a counter from provider names.
2|//! A committed intent is a permanent fence until exact readback is published.
3|use super::*;
4|
5|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
6|#[serde(deny_unknown_fields)]
7|pub struct NativeCreationRequest {
8|    pub operation_id: String,
9|    pub actor_id: String,
10|    pub caller_session: String,
11|    pub caller_genesis: String,
12|    pub owner_kind: String,
13|    pub logical_target: String,
14|    pub request_digest: String,
15|    pub request_json: String,
16|}
17|
18|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
19|#[serde(deny_unknown_fields)]
20|pub struct NativeCreationRecord {
21|    pub request: NativeCreationRequest,
22|    pub number: i64,
23|    pub name: String,
24|    pub phase: String,
25|    pub native_uuid: String,
26|}
27|
28|pub fn is_numbered_native_name(name: &str) -> bool {
29|    name.strip_prefix("ID-").is_some_and(|number| {
30|        number.parse::<i64>().is_ok_and(|n| n > 0 && n.to_string() == number)
31|    })
32|}
33|
34|fn records(tx: &MultiTransaction) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
35|    query(tx, "?[document] := *native_container_creations{document}", Params::new())?
36|        .rows.iter().map(|row| {
37|            let record: NativeCreationRecord = serde_json::from_str(&string(row, 0)?)?;
38|            if record.number <= 0 || record.name != format!("ID-{}", record.number)
39|                || !matches!(record.phase.as_str(), "intent" | "bound" | "complete")
40|                || (record.phase != "intent" && uuid::Uuid::parse_str(&record.native_uuid)
41|                    .map_or(true, |id| id.to_string() != record.native_uuid))
42|            {
43|                return Err(err("native creation journal is corrupt"));
44|            }
45|            Ok(record)
46|        }).collect()
47|}
48|
49|pub(super) fn binding_in_tx(tx: &MultiTransaction, name: &str)
50|    -> std::result::Result<Option<NativeCreationRecord>, CozoError>
51|{
52|    let mut found = records(tx)?.into_iter().filter(|row| row.name == name);
53|    let result = found.next();
54|    if found.next().is_some() { return Err(err("duplicate native name binding")); }
55|    Ok(result)
56|}
57|
58|fn put(tx: &MultiTransaction, record: &NativeCreationRecord) -> std::result::Result<(), CozoError> {
59|    query(tx, "?[operation_id,document] <- [[$op,$doc]] :put native_container_creations {operation_id => document}",
60|        BTreeMap::from([
61|            ("op".into(), DataValue::Str(record.request.operation_id.as_str().into())),
62|            ("doc".into(), DataValue::Str(serde_json::to_string(record)?.into())),
63|        ]))?;
64|    Ok(())
65|}
66|
67|fn sequence(tx: &MultiTransaction, rows: &[NativeCreationRecord])
68|    -> std::result::Result<(i64, String), CozoError>
69|{
70|    let result = query(tx, "?[next,pending] := *native_container_sequence{key,next,pending}, key = 'default'", Params::new())?;
71|    let (next, pending) = match result.rows.as_slice() {
72|        [] if rows.is_empty() => {
73|            let marker = query(tx, "?[completed] := *schema_migrations{name,completed}, name = 'native-container-sequence-v1'", Params::new())?;
74|            if !marker.rows.is_empty() { return Err(err("native creation sequence is missing; refusing reset")); }
75|            (1, String::new())
76|        }
77|        [row] => (integer(row, 0)?, string(row, 1)?),
78|        _ => return Err(err("native creation sequence is missing or corrupt")),
79|    };
80|    let mut sorted = rows.iter().collect::<Vec<_>>();
81|    sorted.sort_by_key(|r| r.number);
82|    let mut expected = 1i64;
83|    for row in sorted {
84|        if row.number != expected
85|            || (row.number < next && row.phase != "complete")
86|            || (row.number == next && (row.phase == "complete" || row.request.operation_id != pending))
87|            || row.number > next
88|        { return Err(err("native creation history is incomplete; refusing sequence recovery")); }
89|        expected = expected.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
90|    }
91|    if next < 1 || (pending.is_empty() && expected != next)
92|        || (!pending.is_empty() && next.checked_add(1) != Some(expected))
93|    { return Err(err("native sequence and pending fence disagree")); }
94|    Ok((next, pending))
95|}
96|
97|fn put_sequence(tx: &MultiTransaction, next: i64, pending: &str) -> std::result::Result<(), CozoError> {
98|    query(tx, "?[key,next,pending] <- [['default',$next,$pending]] :put native_container_sequence {key => next,pending}",
99|        BTreeMap::from([("next".into(), dv_int(next)), ("pending".into(), DataValue::Str(pending.into()))]))?;
100|    query(tx, "?[name,completed] <- [['native-container-sequence-v1',true]] :put schema_migrations {name => completed}", Params::new())?;
101|    Ok(())
102|}
