104|impl CozoGraphShuttle {
105|    pub fn native_creation_records(&self) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
106|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
107|        let tx = self.db.multi_transaction(false);
108|        let rows = records(&tx)?;
109|        sequence(&tx, &rows)?;
110|        commit_checked(&tx)?;
111|        Ok(rows)
112|    }
113|
114|    /// `fresh` is the only permission to issue POST, returned after the barrier.
115|    /// Replays, including intent-only replays, may only read/reconcile.
116|    pub fn reserve_native_creation(&self, request: NativeCreationRequest, observed_names: &[String])
117|        -> std::result::Result<(NativeCreationRecord, bool), CozoError>
118|    {
119|        if self.identity_directory.is_none() { return Err(err("native allocation requires persistent Cozo")); }
120|        if uuid::Uuid::parse_str(&request.operation_id).map_or(true, |id| id.to_string() != request.operation_id)
121|            || request.actor_id.is_empty() || request.caller_session.is_empty() || request.caller_genesis.is_empty()
122|            || !matches!(request.owner_kind.as_str(), "identity" | "project" | "incus")
123|            || request.logical_target.is_empty() || !valid_root_repair_digest(&request.request_digest)
124|            || request.request_json.len() > 65536
125|        { return Err(err("invalid native creation intent")); }
126|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
127|        self.sync_identity_store()?;
128|        let tx = self.db.multi_transaction(true);
129|        let rows = records(&tx)?;
130|        let (next, pending) = sequence(&tx, &rows)?;
131|        for name in observed_names.iter().filter(|n| n.starts_with("ID-")) {
132|            if !rows.iter().any(|row| &row.name == name) {
133|                return Err(err("untracked ID-N native name; refusing allocation or max+1 recovery"));
134|            }
135|        }
136|        if let Some(row) = rows.iter().find(|row| row.request.operation_id == request.operation_id) {
137|            if row.request != request { return Err(err("native operation_id reused with different caller or request")); }
138|            commit_checked(&tx)?;
139|            return Ok((row.clone(), false));
140|        }
141|        if !pending.is_empty() { return Err(err("native creation unresolved; reconcile the owning operation before allocating another name")); }
142|        if request.owner_kind != "incus" && rows.iter().any(|row| row.request.owner_kind == request.owner_kind
143|            && row.request.logical_target == request.logical_target && observed_names.contains(&row.name))
144|        { return Err(err("logical target already has a native container; retain its binding")); }
145|        next.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
146|        let record = NativeCreationRecord { request, number: next, name: format!("ID-{next}"), phase: "intent".into(), native_uuid: String::new() };
147|        if observed_names.contains(&record.name) { return Err(err("native name collision")); }
148|        put(&tx, &record)?;
149|        put_sequence(&tx, next, &record.request.operation_id)?;
